import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
import { SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY } from './config.js';

const configured = SUPABASE_URL.startsWith('https://') && !SUPABASE_URL.includes('PASTE_') && SUPABASE_PUBLISHABLE_KEY && !SUPABASE_PUBLISHABLE_KEY.includes('PASTE_');
const supabase = configured ? createClient(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, { auth: { persistSession: false, autoRefreshToken: true, detectSessionInUrl: false } }) : null;
const $ = (s) => document.querySelector(s);
const $$ = (s) => [...document.querySelectorAll(s)];
const state = { session: null, user: null, page: 'dashboard', medicines: [], batches: [], suppliers: [], receipts: [], details: [], movements: [], options: [], pendingOptionDelete: null, modalType: null, editId: null, editBatchId: null, busy: false, tableSort: { obat: { key: 'kode', dir: 'asc' }, masuk: { key: 'tanggal', dir: 'desc' }, keluar: { key: 'tanggal', dir: 'desc' } } };
const defaultOptions = { kategori: ['Obat Keras','Obat Bebas Terbatas','Obat Bebas','Jamu / Obat Herbal Terstandar','Alat Kesehatan'], bentuk_sediaan: ["Elektronik Digital","Infusion Set","Kantong Karet Klasik","Kapas Bulatan","Kapas Lembaran","Kapas Roll","Kasa hidrofil","Kasa Steril","Larutan Infus","Larutan Steril Non-Pirogenik","Lembaran Alas Datar","Masker Medis","Perban Elastis","Perban Kain Elastis","Pipet Dot Bayi","Pipet Obat","Plester","Plester Luka","Plester Roll","Sarung Tangan","Sarung Tangan Steril","Suntikan","Kondom","Tablet","Tisu Basah Antiseptik","Kapsul","Sirup","Tablet Kunyah","Tablet Salut Selaput","Salep","Kaplet","Krim","sampo Cair","Sampo Cair","Sampo Cairan Kental","Minyak Oles Cair","Sabun Batang","Salep Kulit, Area Mata","Larutan Tetes Mata Steril","Cairan Konsentrat","Larutan Antiseptik","Cairan Obat Luar","Serbuk Kristal","Sirup (Sachet)","Balsem/Krim Oles","Roll On","Serbuk Tabur (Sachet)","Minyak Esensial Aromaterapi","Sachet (Serbuk)","Serbuk (Sachet)","Kaplet Salut Selaput","Tablet (kuning)","Kapsul Lepas Lambat","Bedak Tabur","Bedak Tabur (Sachet)","Krim Cair/Lotion","Krim Topikal","Gel","Plester gel","Tablet Salut Gula","Salep Topikal","Kapsul Lepas Tunda","Serbuk (Sachet )","Minyak Aromaterapi","Tablet Hisap","Minyak Cair (Roll On)","Balsem Aromaterapi","Minyak Angin Aromaterapi (Roll On)","Kaplet Salut Gula","Koyo/Plester","Tablet Enterik","Tablet Salut Enterik","Krim Oles","Minyak Gosok dan Pijat","Tablet Larut Air","Larutan Steril","Pasta Gigi","Krim Topikal/Lotion Cuci","Lotion","Cairan Semprot Rambut","Cairan Tetes Telinga","Krim Perekat","Cairan Semprot Mulut","Blok/Potongan Padat","Larutan Cair Antiseptik","Cairan Obat Kumur","Gel Rektal (Micro-Enema)","Tablet Salut Enteric","Cairan Toner","Stik (midstream)","Strip Uji","Tablet Hisap/Kunyah","Supositoria"], satuan_dasar: ["Dus","Strip","Tablet","Kaplet","Kapsul","Lembar","Sachet","Pcs"] };
function loadOptionSettings(){ try { const saved=JSON.parse(localStorage.getItem('finkacare-medicine-options')||'{}'); return Object.fromEntries(Object.entries(defaultOptions).map(([key,defaults])=>[key,Array.isArray(saved[key])&&saved[key].length?saved[key]:defaults])); } catch(_) { return {...defaultOptions}; } }
const medicineOptions = loadOptionSettings();
function saveOptionSettings(){ try { localStorage.setItem('finkacare-medicine-options',JSON.stringify(medicineOptions)); } catch(_) {} }
function categoryMeta(value){ const raw=String(value||'').trim(); const v=raw.toLowerCase(); if(v==='k'||v.includes('keras'))return {label:v==='k'?'Obat Keras':raw,color:'red'}; if(v==='ak'||v.includes('alat kesehatan'))return {label:v==='ak'?'Alat Kesehatan':raw,color:'purple'}; if(v.includes('jamu')||v.includes('herbal'))return {label:raw,color:'yellow'}; if(v.includes('bebas terbatas'))return {label:raw,color:'blue'}; if(v.includes('obat bebas'))return {label:raw,color:'green'}; return {label:raw,color:'neutral'}; }
function categoryTag(value){ if(!value)return '—'; const m=categoryMeta(value); return `<span class="category-tag ${m.color}"><span class="category-dot"></span>${esc(m.label)}</span>`; }
const tableNames = { obat:'obat', batch:'batch_obat', supplier:'supplier', penerimaan:'penerimaan', detail:'detail_penerimaan', mutasi:'mutasi_stok' };

function esc(v=''){ return String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function money(v){ return v == null || v === '' ? '—' : new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(v)||0); }
function num(v){ return new Intl.NumberFormat('id-ID').format(Number(v)||0); }
function dateFmt(v){ if(!v) return '—'; const d = new Date(`${String(v).slice(0,10)}T00:00:00`); return Number.isNaN(d.getTime()) ? esc(v) : new Intl.DateTimeFormat('id-ID',{day:'2-digit',month:'short',year:'numeric'}).format(d); }
function today(){ return new Date().toISOString().slice(0,10); }
function toast(message){ const el=$('#toast'); el.textContent=message; el.classList.add('show'); clearTimeout(toast.timer); toast.timer=setTimeout(()=>el.classList.remove('show'),3600); }
function setError(el,message){ el.textContent=message||''; }
function initials(user){ const part=(user?.email||'Admin').split('@')[0]; return part.slice(0,2).toUpperCase(); }
function showAuth(){ $('#authView').classList.remove('hidden'); $('#appView').classList.add('hidden'); }
function showApp(){ $('#authView').classList.add('hidden'); $('#appView').classList.remove('hidden'); const name=state.user?.email?.split('@')[0]||'Admin'; const email=state.user?.email||'Akun administrator'; $('#sidebarUserName').textContent=name; $('#sidebarAvatar').textContent=initials(state.user); $('#topAvatar').textContent=initials(state.user); $('#topUserName').textContent=name; $('#profileMenuName').textContent=name; $('#profileMenuEmail').textContent=email; }
function emptyRow(cols,message='Belum ada data.'){ return `<tr><td class="empty-cell" colspan="${cols}">${esc(message)}</td></tr>`; }
function statusTag(text,kind='green'){ return `<span class="status-tag ${kind}">${esc(text)}</span>`; }
function medicineStock(medicineId){ return state.batches.filter(b=>String(b.obat_id)===String(medicineId)).reduce((n,b)=>n+(Number(b.stok_tersedia)||0),0); }
function medicineStatus(m){ const stock=medicineStock(m.id); const min=Number(m.stok_minimum)||0; if(stock<=min) return statusTag(stock===0?'Stok habis':'Stok rendah',stock===0?'red':'amber'); return statusTag('Stok aman','green'); }
function batchStatus(b){ if(!b.tanggal_kedaluwarsa) return {text:'Tanggal belum diisi',kind:'amber',days:null}; const days=Math.ceil((new Date(`${b.tanggal_kedaluwarsa}T00:00:00`).getTime()-new Date(`${today()}T00:00:00`).getTime())/86400000); if(days<0)return{text:'Kedaluwarsa',kind:'red',days}; if(days<=90)return{text:`${days} hari lagi`,kind:'amber',days}; return{text:'Masih aman',kind:'green',days}; }
function batchMedicine(b){ return state.medicines.find(m=>m.id===b.obat_id); }
function movementType(m){ return String(m.jenis_mutasi||'').toLowerCase(); }
function isOut(m){ return /keluar|out|penjualan|pemakaian|retur_keluar|penyesuaian_keluar/.test(movementType(m)); }
function authError(error){ const msg=String(error?.message||''); if(/invalid login credentials/i.test(msg)) return 'Email atau password tidak sesuai.'; if(/email not confirmed/i.test(msg)) return 'Email akun belum dikonfirmasi di Supabase Authentication.'; if(/failed to fetch/i.test(msg)) return 'Tidak dapat menghubungi Supabase. Periksa URL project, key, dan koneksi internet.'; return msg||'Terjadi kesalahan. Silakan coba lagi.'; }

$('#yearNow').textContent=new Date().getFullYear();
$('#todayDate').textContent=new Intl.DateTimeFormat('id-ID',{weekday:'short',day:'numeric',month:'short',year:'numeric'}).format(new Date());
$('#togglePassword').addEventListener('click',()=>{ const input=$('#loginPassword'); const show=input.type==='password'; input.type=show?'text':'password'; $('#togglePassword').textContent=show?'Sembunyi':'Lihat'; });
$('#loginForm').addEventListener('submit', async e=>{ e.preventDefault(); setError($('#loginError'),''); if(!supabase){ setError($('#loginError'),'Konfigurasi Supabase belum diisi. Buka config.js lalu masukkan Project URL dan Publishable Key.'); return; } const button=$('#loginButton'); button.disabled=true; button.textContent='Memeriksa akun...'; try{ const {data,error}=await supabase.auth.signInWithPassword({email:$('#loginEmail').value.trim(),password:$('#loginPassword').value}); if(error) throw error; state.session=data.session; state.user=data.user; await startApp(); }catch(err){ setError($('#loginError'),authError(err)); }finally{ button.disabled=false; button.innerHTML='Masuk ke dashboard <span>→</span>'; } });
async function logout(button){ if(button) button.disabled=true; try { if(supabase){ const {error}=await supabase.auth.signOut({scope:'local'}); if(error) throw error; } state.session=null; state.user=null; $('#profileDropdown').classList.add('hidden'); $('#profileButton').setAttribute('aria-expanded','false'); showAuth(); $('#loginPassword').value=''; setError($('#loginError'),''); toast('Kamu telah keluar dari akun.'); } catch(error) { toast(`Gagal logout: ${authError(error)}`); console.error(error); } finally { if(button) button.disabled=false; } }
$('#logoutButton').addEventListener('click',()=>logout($('#logoutButton')));
$('#profileLogoutButton').addEventListener('click',()=>logout($('#profileLogoutButton')));
$('#profileButton').addEventListener('click',()=>{ const menu=$('#profileDropdown'); const opening=menu.classList.contains('hidden'); menu.classList.toggle('hidden',!opening); $('#profileButton').setAttribute('aria-expanded',String(opening)); });
document.addEventListener('click',event=>{ if(!event.target.closest('.profile-menu-wrap')){ $('#profileDropdown').classList.add('hidden'); $('#profileButton').setAttribute('aria-expanded','false'); } });
document.addEventListener('keydown',event=>{ if(event.key==='Escape'){ $('#profileDropdown').classList.add('hidden'); $('#profileButton').setAttribute('aria-expanded','false'); } });
function setTheme(isDark){ document.body.classList.toggle('dark-mode',isDark); $('#themeIcon').textContent=isDark?'☀':'☾'; $('#themeToggle').setAttribute('aria-label',isDark?'Aktifkan light mode':'Aktifkan dark mode'); $('#themeToggle').title=isDark?'Aktifkan light mode':'Aktifkan dark mode'; $('.theme-toggle-label').textContent=isDark?'Light mode':'Dark mode'; }
let darkTheme=false; try{darkTheme=localStorage.getItem('finkacare-theme')==='dark';}catch(_){} setTheme(darkTheme);
$('#themeToggle').addEventListener('click',()=>{ const dark=!document.body.classList.contains('dark-mode'); setTheme(dark); try{localStorage.setItem('finkacare-theme',dark?'dark':'light');}catch(_){} });
if(!configured){ $('#connectionText').textContent='Konfigurasi diperlukan'; $('.connection-dot').style.background='#d49b35'; }

async function startApp(){ showApp(); await loadAll(); navigate('dashboard'); }
async function getRows(table,order=null,ascending=false){ let query=supabase.from(table).select('*'); if(order) query=query.order(order,{ascending}); const {data,error}=await query.limit(2000); if(error) throw error; return data||[]; }
async function loadAll(){ if(!supabase||!state.user)return; $('#connectionText').textContent='Memuat data'; try{ const [med,batch,sup,rec,det,mov]=await Promise.all([getRows(tableNames.obat),getRows(tableNames.batch,'tanggal_kedaluwarsa',true),getRows(tableNames.supplier,'nama_supplier',true),getRows(tableNames.penerimaan,'tanggal_penerimaan',false),getRows(tableNames.detail, null),getRows(tableNames.mutasi,'created_at',false)]); let opt=[]; try{opt=await getRows('pengaturan_opsi');}catch(optionError){console.warn('Tabel pengaturan_opsi belum tersedia; opsi bawaan digunakan sementara.',optionError);} state.options=opt; state.medicines=med; state.batches=batch; state.suppliers=sup; state.receipts=rec; state.details=det; state.movements=mov; $('#connectionText').textContent='Terhubung'; $('.connection-dot').style.background='#25a77c'; renderAll(); }catch(error){ $('#connectionText').textContent='Periksa akses'; $('.connection-dot').style.background='#c74747'; toast(`Gagal memuat data: ${authError(error)}. Periksa nama kolom, RLS, dan kebijakan akses.`); console.error(error); renderAll(); } }
function renderAll(){ renderDashboard(); renderMedicines(); renderBatches(); renderSuppliers(); renderReceipts(); renderMovements(); renderReport(); updateFilters(); syncSortIndicators(); }
function renderDashboard(){ $('#statMedicines').textContent=num(state.medicines.length); $('#statStock').textContent=num(state.batches.reduce((n,b)=>n+(Number(b.stok_tersedia)||0),0)); $('#statLow').textContent=num(state.medicines.filter(m=>medicineStock(m.id)<=(Number(m.stok_minimum)||0)).length); const atRisk=state.batches.filter(b=>{const s=batchStatus(b);return s.days!==null&&s.days<=90;}); $('#statExpiry').textContent=num(atRisk.length); $('#expiryNavCount').textContent=num(atRisk.length); const recent=[...state.movements].sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||''))).slice(0,5); $('#activityList').innerHTML=recent.length?recent.map(m=>{const b=state.batches.find(x=>x.id===m.batch_id);const med=b&&batchMedicine(b);const out=isOut(m);return `<div class="activity-item"><span class="activity-symbol ${out?'out':''}">${out?'↗':'↙'}</span><div class="activity-detail"><b>${esc(m.jenis_mutasi||'Mutasi stok')} · ${esc(med?.nama_obat||'Obat tidak ditemukan')}</b><small>${dateFmt(m.created_at)}${m.referensi?' · '+esc(m.referensi):''}</small></div><span class="activity-amount">${out?'−':'+'}${num(m.jumlah)}</span></div>`;}).join(''):emptyRow(1,'Belum ada aktivitas mutasi stok.'); const attention=[]; state.medicines.filter(m=>medicineStock(m.id)<=(Number(m.stok_minimum)||0)).slice(0,4).forEach(m=>attention.push(`<div class="attention-item"><span class="attention-symbol">!</span><div class="attention-detail"><b>${esc(m.nama_obat)}</b><small>Stok ${num(medicineStock(m.id))} ${esc(m.satuan_dasar||'unit')} · minimum ${num(m.stok_minimum)}</small></div></div>`)); state.batches.filter(b=>{const s=batchStatus(b);return s.days!==null&&s.days<=90;}).slice(0,4).forEach(b=>{const s=batchStatus(b);attention.push(`<div class="attention-item"><span class="attention-symbol ${s.kind==='red'?'red':''}">◷</span><div class="attention-detail"><b>${esc(batchMedicine(b)?.nama_obat||'Obat')}</b><small>Batch ${esc(b.nomor_batch||'—')} · ${s.text}</small></div></div>`);}); $('#attentionList').innerHTML=attention.slice(0,6).join('')||'<div class="loading-state">Tidak ada hal yang perlu diperiksa saat ini.</div>'; const latest=[...state.medicines].sort((a,b)=>String(b.updated_at||b.created_at||'').localeCompare(String(a.updated_at||a.created_at||''))).slice(0,6); $('#dashboardMedicineRows').innerHTML=latest.length?latest.map(m=>`<tr><td>${esc(m.kode_obat||'—')}</td><td><span class="cell-title">${esc(m.nama_obat)}</span><span class="cell-sub">${esc(m.satuan_dasar||'')}</span></td><td>${categoryTag(m.kategori)}</td><td>${num(medicineStock(m.id))} ${esc(m.satuan_dasar||'')}</td><td>${medicineStatus(m)}</td></tr>`).join(''):emptyRow(5,'Belum ada data obat. Tambahkan obat untuk memulai.'); }
function sortRows(rows,table,getter){const cfg=state.tableSort[table];if(!cfg)return rows;return [...rows].sort((a,b)=>{const av=getter(a,cfg.key),bv=getter(b,cfg.key);const an=av!==''&&av!==null&&av!==undefined&&Number.isFinite(Number(av)),bn=bv!==''&&bv!==null&&bv!==undefined&&Number.isFinite(Number(bv));let cmp;if(an&&bn)cmp=Number(av)-Number(bv);else cmp=String(av??'').localeCompare(String(bv??''),'id',{numeric:true,sensitivity:'base'});return cfg.dir==='asc'?cmp:-cmp;});}
function syncSortIndicators(){document.querySelectorAll('[data-sort-table][data-sort-key]').forEach(btn=>{const cfg=state.tableSort[btn.dataset.sortTable];const ind=btn.querySelector('.sort-indicator');if(ind&&cfg)ind.textContent=btn.dataset.sortKey===cfg.key?(cfg.dir==='asc'?'▲':'▼'):'↕';});}
function sortHead(table,key,label){const cfg=state.tableSort[table],active=cfg?.key===key;return `<button type="button" class="table-sort-button" data-sort-table="${table}" data-sort-key="${key}" aria-label="Urutkan ${label}">${label}<span class="sort-indicator">${active?(cfg.dir==='asc'?'▲':'▼'):'↕'}</span></button>`;}
function renderMedicines(){ const q=($('#medicineSearch')?.value||'').toLowerCase(); const cat=$('#medicineCategoryFilter')?.value||''; const filtered=state.medicines.filter(m=>(`${m.kode_obat||''} ${m.nama_obat||''} ${m.kategori||''}`).toLowerCase().includes(q)&&(!cat||m.kategori===cat)); const rows=sortRows(filtered,'obat',(m,k)=>({kode:m.kode_obat,nama:m.nama_obat,kategori:m.kategori,bentuk:m.bentuk_sediaan,stok:medicineStock(m.id),minimum:m.stok_minimum,harga:m.harga_jual}[k])); $('#medicineRows').innerHTML=rows.length?rows.map(m=>`<tr><td>${esc(m.kode_obat||'—')}</td><td><span class="cell-title">${esc(m.nama_obat)}</span><span class="cell-sub">${esc(m.satuan_dasar||'—')}</span></td><td>${categoryTag(m.kategori)}</td><td>${esc(m.bentuk_sediaan||'—')}</td><td><span class="cell-title">${num(medicineStock(m.id))}</span><span class="cell-sub">${esc(m.satuan_dasar||'')}</span></td><td>${m.stok_minimum==null||m.stok_minimum===''?'—':num(m.stok_minimum)}</td><td>${money(m.harga_jual)}</td><td><div class="row-actions"><button class="action-btn" data-edit="obat" data-id="${esc(m.id)}">Ubah</button><button class="action-btn" data-delete="obat" data-id="${esc(m.id)}">Hapus</button></div></td></tr>`).join(''):emptyRow(8,'Data obat belum tersedia atau tidak ditemukan.'); $('#medicineCount').textContent=`Menampilkan ${rows.length} dari ${state.medicines.length} data obat`; }
function renderBatches(){ const q=($('#batchSearch')?.value||'').toLowerCase(); const f=$('#batchFilter')?.value||'all'; const rows=state.batches.filter(b=>{const med=batchMedicine(b);const s=batchStatus(b);return `${med?.nama_obat||''} ${b.nomor_batch||''}`.toLowerCase().includes(q)&&(f==='all'||(f==='expired'&&s.days!==null&&s.days<0)||(f==='soon'&&s.days!==null&&s.days>=0&&s.days<=90)||(f==='safe'&&(s.days===null||s.days>90)));}); const soon=state.batches.filter(b=>batchStatus(b).days!==null&&batchStatus(b).days>=0&&batchStatus(b).days<=90).length;const expired=state.batches.filter(b=>batchStatus(b).days!==null&&batchStatus(b).days<0).length;$('#batchTotal').textContent=num(state.batches.length);$('#batchSoon').textContent=num(soon);$('#batchExpired').textContent=num(expired); $('#batchRows').innerHTML=rows.length?rows.map(b=>{const med=batchMedicine(b),s=batchStatus(b);return `<tr><td><span class="cell-title">${esc(med?.nama_obat||'Obat tidak ditemukan')}</span><span class="cell-sub">${esc(med?.kode_obat||'')}</span></td><td>${esc(b.nomor_batch||'—')}</td><td>${dateFmt(b.tanggal_kedaluwarsa)}</td><td>${num(b.stok_tersedia)} ${esc(med?.satuan_dasar||'')}</td><td>${statusTag(s.text,s.kind)}</td></tr>`;}).join(''):emptyRow(5,'Belum ada batch yang sesuai.');$('#batchCount').textContent=`Menampilkan ${rows.length} dari ${state.batches.length} batch`; }
function renderSuppliers(){const q=($('#supplierSearch')?.value||'').toLowerCase();const rows=state.suppliers.filter(s=>`${s.nama_supplier||''} ${s.kontak||''}`.toLowerCase().includes(q));$('#supplierRows').innerHTML=rows.length?rows.map(s=>`<tr><td><span class="cell-title">${esc(s.nama_supplier)}</span></td><td>${esc(s.kontak||'—')}</td><td>${esc(s.alamat||'—')}</td><td><div class="row-actions"><button class="action-btn" data-edit="supplier" data-id="${esc(s.id)}">Ubah</button><button class="action-btn" data-delete="supplier" data-id="${esc(s.id)}">Hapus</button></div></td></tr>`).join(''):emptyRow(4,'Belum ada data supplier.');$('#supplierCount').textContent=`Menampilkan ${rows.length} dari ${state.suppliers.length} supplier`;}
function renderReceipts(){const q=($('#incomingSearch')?.value||'').toLowerCase();const filtered=state.receipts.filter(r=>`${state.suppliers.find(s=>String(s.id)===String(r.supplier_id))?.nama_supplier||''} ${r.catatan||''} ${r.tanggal_penerimaan||''}`.toLowerCase().includes(q));const rows=sortRows(filtered,'masuk',(r,k)=>({tanggal:r.tanggal_penerimaan,supplier:state.suppliers.find(s=>String(s.id)===String(r.supplier_id))?.nama_supplier||'',catatan:r.catatan||'',dibuat:r.created_at?.slice(0,10)||''}[k]));$('#incomingRows').innerHTML=rows.length?rows.map(r=>`<tr><td>${dateFmt(r.tanggal_penerimaan)}</td><td>${esc(state.suppliers.find(s=>String(s.id)===String(r.supplier_id))?.nama_supplier||'—')}</td><td>${esc(r.catatan||'—')}</td><td>${dateFmt(r.created_at?.slice(0,10))}</td><td><div class="row-actions"><button class="action-btn" data-receipt-view="${esc(r.id)}">Detail</button><button class="action-btn" data-receipt-edit="${esc(r.id)}">Ubah</button></div></td></tr>`).join(''):emptyRow(5,'Belum ada penerimaan yang tercatat.');$('#incomingCount').textContent=`Menampilkan ${rows.length} dari ${state.receipts.length} penerimaan`; }
function renderMovements(){const q=($('#outgoingSearch')?.value||'').toLowerCase();const filtered=state.movements.filter(m=>isOut(m)).filter(m=>{const b=state.batches.find(x=>x.id===m.batch_id),med=b&&batchMedicine(b);return `${med?.nama_obat||''} ${b?.nomor_batch||''} ${m.referensi||''}`.toLowerCase().includes(q);});const rows=sortRows(filtered,'keluar',(m,k)=>{const b=state.batches.find(x=>x.id===m.batch_id),med=b&&batchMedicine(b);return {tanggal:m.created_at||'',nama:med?.nama_obat||'',batch:b?.nomor_batch||'',jenis:m.jenis_mutasi||'',jumlah:m.jumlah,referensi:m.referensi||''}[k];});$('#outgoingRows').innerHTML=rows.length?rows.map(m=>{const b=state.batches.find(x=>x.id===m.batch_id),med=b&&batchMedicine(b);return `<tr><td>${dateFmt(m.created_at)}</td><td><span class="cell-title">${esc(med?.nama_obat||'—')}</span></td><td>${esc(b?.nomor_batch||'—')}</td><td>${statusTag(m.jenis_mutasi||'Keluar','blue')}</td><td>${num(m.jumlah)} ${esc(med?.satuan_dasar||'')}</td><td>${esc(m.referensi||'—')}</td></tr>`;}).join(''):emptyRow(6,'Belum ada mutasi keluar yang tercatat.');$('#outgoingCount').textContent=`Menampilkan ${rows.length} mutasi keluar`;}
function renderReport(){const rows=state.medicines.map(m=>({m,stock:state.batches.filter(b=>String(b.obat_id)===String(m.id)).reduce((n,b)=>n+(Number(b.stok_tersedia)||0),0)}));$('#reportRows').innerHTML=rows.length?rows.map(r=>`<tr><td>${esc(r.m.kode_obat||'—')}</td><td><span class="cell-title">${esc(r.m.nama_obat)}</span></td><td>${num(r.stock)} ${esc(r.m.satuan_dasar||'')}</td></tr>`).join(''):emptyRow(3,'Data persediaan belum tersedia.');}
function updateFilters(){const select=$('#medicineCategoryFilter');if(!select)return;const current=select.value;const cats=[...new Set(state.medicines.map(m=>m.kategori).filter(Boolean))].sort();select.innerHTML='<option value="">Semua kategori</option>'+cats.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');select.value=cats.includes(current)?current:'';}
function navigate(page){state.page=page;$$('.page').forEach(el=>el.classList.toggle('active',el.id===`page-${page}`));$$('.nav-item').forEach(el=>el.classList.toggle('active',el.dataset.page===page));const active=$(`.nav-item[data-page="${page}"]`);$('#breadcrumbTitle').textContent=active?.textContent.trim()||'Dashboard';$('#sidebar').classList.remove('open');$('#mobileOverlay').classList.remove('show');window.scrollTo({top:0,behavior:'smooth'});}
$$('.nav-item').forEach(btn=>btn.addEventListener('click',()=>navigate(btn.dataset.page)));$$('[data-page-link]').forEach(btn=>btn.addEventListener('click',()=>navigate(btn.dataset.pageLink)));$('#mobileMenu').addEventListener('click',()=>{$('#sidebar').classList.add('open');$('#mobileOverlay').classList.add('show');});$('#sidebarClose').addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#mobileOverlay').classList.remove('show');});$('#mobileOverlay').addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#mobileOverlay').classList.remove('show');});
$('#medicineSearch').addEventListener('input',renderMedicines);$('#medicineCategoryFilter').addEventListener('change',renderMedicines);$('#batchSearch').addEventListener('input',renderBatches);$('#batchFilter').addEventListener('change',renderBatches);$('#supplierSearch').addEventListener('input',renderSuppliers);$('#incomingSearch').addEventListener('input',renderReceipts);$('#outgoingSearch').addEventListener('input',renderMovements);$('#refreshMedicines').addEventListener('click',loadAll);$('#refreshSuppliers').addEventListener('click',loadAll);

document.addEventListener('click',e=>{
  const open=e.target.closest('[data-open]');
  if(open){e.preventDefault();try{openModal(open.dataset.open);}catch(error){console.error('Gagal membuka formulir:',error);toast(`Formulir tidak dapat dibuka: ${authError(error)}`);}return;}
  const receiptView=e.target.closest('[data-receipt-view]');
  if(receiptView){e.preventDefault();openReceiptModal(receiptView.dataset.receiptView,false);return;}
  const receiptEdit=e.target.closest('[data-receipt-edit]');
  if(receiptEdit){e.preventDefault();openReceiptModal(receiptEdit.dataset.receiptEdit,true);return;}
  const edit=e.target.closest('[data-edit]');
  if(edit){e.preventDefault();openModal(edit.dataset.edit,edit.dataset.id);return;}
  const del=e.target.closest('[data-delete]');
  if(del){e.preventDefault();deleteRow(del.dataset.delete,del.dataset.id);return;}
  const exp=e.target.closest('[data-export]');
  if(exp){e.preventDefault();exportCsv(exp.dataset.export);}
});
const formFields={supplier:[['nama_supplier','Nama supplier','text',true],['kontak','Kontak supplier (telepon/email)','text',false],['alamat','Alamat','textarea',false]]};
function selectField(name,label,options,required=true,value=''){const items=(Array.isArray(options)?options:[]).slice().sort((a,b)=>String(a.label).localeCompare(String(b.label),'id',{sensitivity:'base',numeric:true}));return `<div class="field"><label>${esc(label)}${required?' *':''}<select name="${esc(name)}" ${required?'required':''}><option value="">Pilih ${esc(label.toLowerCase())}</option>${items.map(item=>`<option value="${esc(item.value)}" ${String(item.value)===String(value)?'selected':''}>${esc(item.label)}</option>`).join('')}</select></label></div>`;}
function fieldHtml([name,label,type,required],value=''){let input='';if(type==='textarea')input=`<textarea name="${name}" placeholder="${label}" ${required?'required':''}>${esc(value)}</textarea>`;else if(type==='money')input=`<input name="${name}" type="text" inputmode="numeric" data-money="true" value="${value===''||value==null?'':num(value)}" placeholder="Contoh: 15.000" ${required?'required':''}>`;else input=`<input name="${name}" type="${type}" ${type==='number'?'min="0" step="any"':''} value="${esc(value)}" placeholder="${label}" ${required?'required':''}>`;return `<div class="field ${type==='textarea'?'full':''}"><label>${esc(label)}${required?' *':''}${input}</label></div>`;}
function optionField(name,label,value=''){let options;if(name==='satuan_dasar'){options=defaultOptions.satuan_dasar;}else if(name==='bentuk_sediaan'){const legacyDefaults=new Set(['Tablet','Kaplet','Kapsul','Sirup','Sirup (Sachet)','Salep','Krim','Krim Oles','Gel','Tetes Mata','Larutan','Serbuk','Sachet','Kasa Steril','Plester','Masker Medis','Infusion Set','Alat Kesehatan']);const custom=state.options.filter(o=>o.jenis===name).map(o=>o.nilai).filter(o=>!defaultOptions.bentuk_sediaan.includes(o)&&!legacyDefaults.has(o));options=[...defaultOptions.bentuk_sediaan,...custom.filter(o=>!defaultOptions.bentuk_sediaan.includes(o))];}else{options=state.options.filter(o=>o.jenis===name).map(o=>o.nilai);if(!options.length)options=medicineOptions[name]||[];}const found=(value&&!options.includes(value)&&name!=='satuan_dasar'?[value,...options]:options).slice().sort((a,b)=>String(a).localeCompare(String(b),'id',{sensitivity:'base',numeric:true}));return `<div class="field option-field"><label>${esc(label)} *</label><input type="hidden" name="${name}" value="${esc(value)}" data-option-value-input="${name}"><button type="button" class="option-picker-trigger" data-option-toggle="${name}" aria-expanded="false"><span data-option-current-label="${name}">${esc(value||`Pilih ${label.toLowerCase()}`)}</span><span class="option-chevron" aria-hidden="true">▾</span></button><div class="option-picker hidden" data-option-panel="${name}" role="group" aria-label="Pilihan ${esc(label.toLowerCase())}"><div class="option-picker-scroll"><div class="option-search-wrap"><input type="search" class="option-search" placeholder="Cari ${esc(label.toLowerCase())}..." aria-label="Cari ${esc(label.toLowerCase())}" data-option-search="${name}"></div><div class="option-choice-list">${found.map(o=>{const fixed=name==='satuan_dasar'||(name==='bentuk_sediaan'&&defaultOptions.bentuk_sediaan.includes(o));return `<div class="option-choice ${o===value?'selected':''}" data-option-row data-search-text="${esc(o.toLocaleLowerCase('id-ID'))}"><button type="button" class="option-select-choice" data-option-select="${name}" data-option-value="${esc(o)}">${esc(o)}${o===value?' <span aria-hidden="true">✓</span>':''}</button>${fixed?'':`<button type="button" class="option-delete-icon" aria-label="Hapus ${esc(o)}" title="Hapus opsi" data-option-delete="${name}" data-option-value="${esc(o)}">×</button>`}</div>`;}).join('')}</div>${name==='satuan_dasar'?'':`<button type="button" class="option-manage-btn" data-option-add="${name}">＋ Tambah ${esc(label.toLowerCase())}</button>`}</div></div></div>`;}
function medicineSelectField(){const medicines=[...state.medicines].sort((a,b)=>String(a.nama_obat||'').localeCompare(String(b.nama_obat||''),'id'));return `<div class="field option-field"><label>Obat *</label><input type="hidden" name="obat_id" value="" data-medicine-value-input><button type="button" class="option-picker-trigger" data-medicine-toggle aria-expanded="false"><span data-medicine-current-label>Pilih obat</span><span class="option-chevron" aria-hidden="true">▾</span></button><div class="option-picker hidden" data-medicine-panel role="group" aria-label="Pilihan obat"><div class="option-picker-scroll"><div class="option-search-wrap"><input type="search" class="option-search" placeholder="Cari nama atau kode obat..." aria-label="Cari obat" data-medicine-search></div><div class="option-choice-list">${medicines.map(m=>{const label=`${m.nama_obat} (${m.satuan_dasar||'unit'})`;const searchText=`${m.nama_obat||''} ${m.kode_obat||''} ${m.bentuk_sediaan||''} ${m.satuan_dasar||''}`.toLocaleLowerCase('id-ID');return `<div class="option-choice" data-option-row data-search-text="${esc(searchText)}"><button type="button" class="option-select-choice" data-medicine-select="${esc(m.id)}" data-medicine-label="${esc(label)}">${esc(label)}${m.kode_obat?`<span class="cell-sub">${esc(m.kode_obat)}</span>`:''}</button></div>`;}).join('')}</div><div class="option-empty hidden" data-medicine-empty>Tidak ada obat yang cocok.</div></div></div></div>`;}
function supplierSelectField(){return `<div class="field option-field"><label>Supplier</label><input type="hidden" name="supplier_id" value="" data-supplier-value-input><button type="button" class="option-picker-trigger" data-supplier-toggle aria-expanded="false"><span data-supplier-current-label>Pilih supplier jika diperlukan</span><span class="option-chevron" aria-hidden="true">▾</span></button><div class="option-picker hidden" data-supplier-panel role="group" aria-label="Pilihan supplier"><div class="option-picker-scroll"><div class="option-search-wrap"><input type="search" class="option-search" placeholder="Cari supplier..." aria-label="Cari supplier" data-supplier-search></div><div class="option-choice-list">${[...state.suppliers].sort((a,b)=>String(a.nama_supplier||'').localeCompare(String(b.nama_supplier||''),'id',{sensitivity:'base'})).map(x=>`<div class="option-choice" data-option-row data-search-text="${esc(x.nama_supplier.toLowerCase())}"><button type="button" class="option-select-choice" data-supplier-select="${esc(x.id)}">${esc(x.nama_supplier)}</button><button type="button" class="option-delete-icon" title="Hapus supplier" aria-label="Hapus supplier ${esc(x.nama_supplier)}" data-supplier-delete="${esc(x.id)}">×</button></div>`).join('')}</div><button type="button" class="option-manage-btn" data-supplier-add>＋ Tambah supplier</button></div></div></div>`;}
function receiptDetailFor(receiptId){return state.details.find(d=>String(d.penerimaan_id)===String(receiptId))||null;}
function receiptBatch(detail){return detail?state.batches.find(b=>String(b.id)===String(detail.batch_id)):null;}
function openReceiptModal(id,edit){const receipt=state.receipts.find(r=>String(r.id)===String(id));if(!receipt){toast('Data penerimaan tidak ditemukan.');return;}const detail=receiptDetailFor(id);const batch=receiptBatch(detail);const med=batch?batchMedicine(batch):null;state.modalType=edit?'masuk-edit':'masuk-view';state.editId=String(id);$('#modalError').textContent='';$('#modalTitle').textContent=edit?'Ubah Detail Stok Masuk':'Detail Stok Masuk';let html='';if(edit){html=selectField('supplier_id','Supplier',state.suppliers.map(s=>({value:s.id,label:s.nama_supplier})),false,receipt.supplier_id??'')+fieldHtml(['tanggal_penerimaan','Tanggal penerimaan','date',true],receipt.tanggal_penerimaan||today())+fieldHtml(['catatan','Catatan','textarea',false],receipt.catatan||'')+`<div class="field full"><div class="form-section-title">Detail obat masuk</div></div>`+selectField('obat_id','Obat',state.medicines.map(m=>({value:m.id,label:`${m.kode_obat||''} · ${m.nama_obat}`})),true,med?.id??'')+fieldHtml(['nomor_batch','Nomor batch','text',true],batch?.nomor_batch||'')+fieldHtml(['tanggal_kedaluwarsa','Tanggal kedaluwarsa','date',true],batch?.tanggal_kedaluwarsa||'')+fieldHtml(['jumlah','Jumlah masuk','number',true],detail?.jumlah??'');}else{html=`<div class="receipt-detail-grid"><div><span>Tanggal penerimaan</span><strong>${dateFmt(receipt.tanggal_penerimaan)}</strong></div><div><span>Supplier</span><strong>${esc(state.suppliers.find(s=>String(s.id)===String(receipt.supplier_id))?.nama_supplier||'—')}</strong></div><div><span>Obat</span><strong>${esc(med?.nama_obat||'Data obat tidak ditemukan')}</strong></div><div><span>Kode obat</span><strong>${esc(med?.kode_obat||'—')}</strong></div><div><span>Nomor batch</span><strong>${esc(batch?.nomor_batch||'—')}</strong></div><div><span>Tanggal kedaluwarsa</span><strong>${dateFmt(batch?.tanggal_kedaluwarsa)}</strong></div><div><span>Jumlah masuk</span><strong>${num(detail?.jumlah)} ${esc(med?.satuan_dasar||'')}</strong></div><div><span>Dicatat pada</span><strong>${dateFmt(receipt.created_at?.slice(0,10))}</strong></div><div class="receipt-detail-note"><span>Catatan</span><strong>${esc(receipt.catatan||'—')}</strong></div></div>`;}$('#modalFields').innerHTML=html;$('#modalBackdrop').classList.remove('hidden');$('#modalSubmit').classList.toggle('hidden',!edit);$('#modalSubmit').textContent='Simpan Perubahan';}
function openModal(type,id=null){state.modalType=type;state.editId=id;state.editBatchId=null;const existing=id?(type==='obat'?state.medicines.find(x=>String(x.id)===String(id)):state.suppliers.find(x=>String(x.id)===String(id))):null;$('#modalTitle').textContent=(id?'Ubah ':'Tambah ')+({obat:'Data Obat',supplier:'Supplier',masuk:'Stok Masuk',keluar:'Stok Keluar'}[type]||'Data');$('#modalError').textContent='';let html='';if(type==='obat'){html=fieldHtml(['kode_obat','Kode obat','text',true],existing?.kode_obat??'').replace('<input name="kode_obat"','<input list="kodeObatSuggestions" name="kode_obat"')+`<datalist id="kodeObatSuggestions">${[...state.medicines].sort((a,b)=>String(a.kode_obat||'').localeCompare(String(b.kode_obat||''),'id',{sensitivity:'base',numeric:true})).map(m=>`<option value="${esc(m.kode_obat||'')}">`).join('')}</datalist>`+fieldHtml(['nama_obat','Nama obat','text',true],existing?.nama_obat??'').replace('<input name="nama_obat"','<input list="namaObatSuggestions" name="nama_obat"')+`<datalist id="namaObatSuggestions">${[...state.medicines].sort((a,b)=>String(a.nama_obat||'').localeCompare(String(b.nama_obat||''),'id',{sensitivity:'base'})).map(m=>`<option value="${esc(m.nama_obat||'')}">`).join('')}</datalist>`+optionField('bentuk_sediaan','Bentuk sediaan',existing?.bentuk_sediaan??'')+fieldHtml(['jenis_obat','Jenis obat','text',false],existing?.jenis_obat??'').replace('<input name="jenis_obat"','<input list="jenisObatSuggestions" name="jenis_obat"')+`<datalist id="jenisObatSuggestions">${[...new Set(state.medicines.map(m=>m.jenis_obat).filter(Boolean))].sort((a,b)=>String(a).localeCompare(String(b),'id',{sensitivity:'base'})).map(v=>`<option value="${esc(v)}">`).join('')}</datalist>`+optionField('kategori','Kategori obat',existing?.kategori??'')+optionField('satuan_dasar','Satuan stok',existing?.satuan_dasar??'')+fieldHtml(['stok_minimum','Batas minimum stok (opsional)','number',false],existing?.stok_minimum??'')+fieldHtml(['harga_jual','Harga jual per satuan (Rp)','money',true],existing?.harga_jual??'');}else if(type==='supplier'){html=formFields[type].map(f=>fieldHtml(f,existing?.[f[0]]??'')).join('');}else if(type==='masuk'){html=supplierSelectField()+medicineSelectField()+fieldHtml(['nomor_batch','Nomor batch','text',true])+fieldHtml(['tanggal_kedaluwarsa','Tanggal kedaluwarsa','date',true])+fieldHtml(['jumlah','Jumlah masuk','number',true])+fieldHtml(['tanggal_penerimaan','Tanggal penerimaan','date',true])+fieldHtml(['catatan','Catatan','textarea',false]);}else if(type==='keluar'){const available=state.batches.filter(b=>Number(b.stok_tersedia)>0);html=selectField('batch_id','Batch obat',available.map(b=>({value:b.id,label:`${batchMedicine(b)?.nama_obat||'Obat'} · ${b.nomor_batch||'Tanpa batch'} · stok ${num(b.stok_tersedia)}`})))+fieldHtml(['jumlah','Jumlah keluar','number',true])+fieldHtml(['referensi','Nomor referensi','text',false])+fieldHtml(['catatan','Catatan','textarea',false]);}$('#modalFields').innerHTML=html;$('#modalSubmit').classList.remove('hidden');$('#modalBackdrop').classList.remove('hidden');if(type==='masuk'){$('[name="tanggal_penerimaan"]').value=today();}$('#modalSubmit').textContent=type==='masuk'?'Simpan Penerimaan':type==='keluar'?'Simpan Pengeluaran':'Simpan Data';}
async function manageOption(action,name,value=''){const label=name==='kategori'?'Kategori obat':name==='bentuk_sediaan'?'Bentuk sediaan':'Satuan stok';if(action==='add'){const input=prompt(`Masukkan opsi baru untuk ${label.toLowerCase()}:`);if(input===null)return;const clean=input.trim();if(!clean){toast('Opsi tidak boleh kosong.');return;}if(state.options.some(o=>o.jenis===name&&o.nilai.toLowerCase()===clean.toLowerCase())){toast('Opsi tersebut sudah tersedia.');return;}try{const {error}=await supabase.from('pengaturan_opsi').insert({jenis:name,nilai:clean});if(error)throw error;const {data,error:readError}=await supabase.from('pengaturan_opsi').select('*').eq('jenis',name).order('nilai');if(readError)throw readError;state.options=state.options.filter(o=>o.jenis!==name).concat(data||[]);const wrapper=$(`[name="${name}"]`)?.closest('.option-field');if(wrapper)wrapper.outerHTML=optionField(name,label,clean);toast('Opsi berhasil ditambahkan.');}catch(err){toast(`Opsi tidak dapat disimpan: ${authError(err)}. Pastikan tabel pengaturan_opsi tersedia di Supabase.`);}}else{state.pendingOptionDelete={name,value};$('#confirmMessage').textContent='Yakin mau dihapus?';$('#confirmBackdrop').classList.remove('hidden');}}
async function addSupplierOption(){const value=prompt('Masukkan nama supplier baru:');if(value===null)return;const clean=value.trim();if(!clean){toast('Nama supplier tidak boleh kosong.');return;}if(state.suppliers.some(x=>x.nama_supplier.toLowerCase()===clean.toLowerCase())){toast('Supplier sudah tersedia.');return;}try{const {error}=await supabase.from('supplier').insert({nama_supplier:clean});if(error)throw error;await loadAll();const wrapper=$('[name="supplier_id"]')?.closest('.option-field');if(wrapper)wrapper.outerHTML=supplierSelectField();toast('Supplier berhasil ditambahkan.');}catch(err){toast(`Supplier tidak dapat ditambahkan: ${authError(err)}`);}}
async function confirmOptionDelete(){const pending=state.pendingOptionDelete;if(!pending)return;try{if(pending.name==='supplier'){const {error}=await supabase.from('supplier').delete().eq('id',pending.value);if(error)throw error;state.suppliers=state.suppliers.filter(x=>String(x.id)!==String(pending.value));}else{const column=pending.name==='kategori'?'kategori':pending.name==='bentuk_sediaan'?'bentuk_sediaan':'satuan_dasar';if(state.medicines.some(m=>String(m[column]||'').toLowerCase()===String(pending.value).toLowerCase()))throw new Error('Opsi sedang digunakan oleh data obat. Ubah data obat terkait sebelum menghapus opsi ini.');const {error}=await supabase.from('pengaturan_opsi').delete().eq('jenis',pending.name).eq('nilai',pending.value);if(error)throw error;state.options=state.options.filter(o=>!(o.jenis===pending.name&&o.nilai===pending.value));const wrapper=$(`[name="${pending.name}"]`)?.closest('.option-field');if(wrapper)wrapper.outerHTML=optionField(pending.name,pending.name==='kategori'?'Kategori obat':pending.name==='bentuk_sediaan'?'Bentuk sediaan':'Satuan stok','');}toast('Data berhasil dihapus.');if(pending.name==='supplier'){await loadAll();const wrapper=$('[name="supplier_id"]')?.closest('.option-field');if(wrapper)wrapper.outerHTML=supplierSelectField();}}catch(err){toast(`Data tidak dapat dihapus: ${authError(err)}. Jika masih dipakai transaksi, data dipertahankan.`);}finally{state.pendingOptionDelete=null;$('#confirmBackdrop').classList.add('hidden');}}
function closeModal(){$('#modalBackdrop').classList.add('hidden');$('#dataForm').reset();$('#modalSubmit').classList.remove('hidden');state.modalType=null;state.editId=null;}
$('#modalClose').addEventListener('click',closeModal);$('#modalCancel').addEventListener('click',closeModal);$('#modalBackdrop').addEventListener('click',e=>{if(e.target===$('#modalBackdrop'))closeModal();});
$('#modalFields').addEventListener('click',e=>{const toggle=e.target.closest('[data-option-toggle]');const supplierToggle=e.target.closest('[data-supplier-toggle]');const medicineToggle=e.target.closest('[data-medicine-toggle]');const medicineChoose=e.target.closest('[data-medicine-select]');const add=e.target.closest('[data-option-add]');const remove=e.target.closest('[data-option-delete]');const choose=e.target.closest('[data-option-select]');const supplierChoose=e.target.closest('[data-supplier-select]');const supplierRemove=e.target.closest('[data-supplier-delete]');const supplierAdd=e.target.closest('[data-supplier-add]');if(toggle){const name=toggle.dataset.optionToggle,field=toggle.closest('.option-field'),panel=field.querySelector(`[data-option-panel="${name}"]`),opening=panel.classList.contains('hidden');panel.classList.toggle('hidden',!opening);toggle.setAttribute('aria-expanded',String(opening));toggle.querySelector('.option-chevron').textContent=opening?'▴':'▾';}if(supplierToggle){const field=supplierToggle.closest('.option-field'),panel=field.querySelector('[data-supplier-panel]'),opening=panel.classList.contains('hidden');panel.classList.toggle('hidden',!opening);supplierToggle.setAttribute('aria-expanded',String(opening));supplierToggle.querySelector('.option-chevron').textContent=opening?'▴':'▾';}if(medicineToggle){const field=medicineToggle.closest('.option-field'),panel=field.querySelector('[data-medicine-panel]'),opening=panel.classList.contains('hidden');panel.classList.toggle('hidden',!opening);medicineToggle.setAttribute('aria-expanded',String(opening));medicineToggle.querySelector('.option-chevron').textContent=opening?'▴':'▾';if(opening)field.querySelector('[data-medicine-search]').focus();}if(medicineChoose){const field=medicineChoose.closest('.option-field');field.querySelector('[data-medicine-value-input]').value=medicineChoose.dataset.medicineSelect;field.querySelector('[data-medicine-current-label]').textContent=medicineChoose.dataset.medicineLabel;field.querySelectorAll('.option-choice').forEach(row=>row.classList.toggle('selected',row.contains(medicineChoose)));field.querySelector('[data-medicine-panel]').classList.add('hidden');field.querySelector('[data-medicine-toggle]').setAttribute('aria-expanded','false');field.querySelector('.option-chevron').textContent='▾';}if(choose){const name=choose.dataset.optionSelect,value=choose.dataset.optionValue;const input=$(`[data-option-value-input="${name}"]`);if(input)input.value=value;const field=choose.closest('.option-field');field.querySelector(`[data-option-current-label="${name}"]`).textContent=value;field.querySelectorAll('.option-choice').forEach(row=>row.classList.toggle('selected',row.contains(choose)));field.querySelectorAll('[data-option-select]').forEach(btn=>{btn.innerHTML=esc(btn.dataset.optionValue)+(btn.dataset.optionValue===value?' <span aria-hidden="true">✓</span>':'');});field.querySelector(`[data-option-panel="${name}"]`).classList.add('hidden');const trigger=field.querySelector(`[data-option-toggle="${name}"]`);trigger.setAttribute('aria-expanded','false');trigger.querySelector('.option-chevron').textContent='▾';}if(supplierChoose){const input=$('[data-supplier-value-input]');if(input)input.value=supplierChoose.dataset.supplierSelect;const field=supplierChoose.closest('.option-field');field.querySelector('[data-supplier-current-label]').textContent=supplierChoose.textContent;field.querySelectorAll('.option-choice').forEach(row=>row.classList.toggle('selected',row.contains(supplierChoose)));field.querySelector('[data-supplier-panel]').classList.add('hidden');field.querySelector('[data-supplier-toggle]').setAttribute('aria-expanded','false');field.querySelector('.option-chevron').textContent='▾';}if(add)manageOption('add',add.dataset.optionAdd);if(remove)manageOption('remove',remove.dataset.optionDelete,remove.dataset.optionValue);if(supplierRemove){state.pendingOptionDelete={name:'supplier',value:supplierRemove.dataset.supplierDelete};$('#confirmMessage').textContent='Yakin mau dihapus?';$('#confirmBackdrop').classList.remove('hidden');}if(supplierAdd)addSupplierOption();});
$('#confirmCancel').addEventListener('click',()=>{$('#confirmBackdrop').classList.add('hidden');state.pendingOptionDelete=null;});$('#confirmDelete').addEventListener('click',confirmOptionDelete);
$('#modalFields').addEventListener('input',e=>{if(e.target.matches('[data-money="true"]')){const digits=e.target.value.replace(/\D/g,'');e.target.value=digits?new Intl.NumberFormat('id-ID').format(Number(digits)):'';}const searchName=e.target.dataset.optionSearch;if(searchName){const field=e.target.closest('.option-field');const q=e.target.value.trim().toLocaleLowerCase('id-ID');field.querySelectorAll('[data-option-row]').forEach(row=>{row.classList.toggle('hidden',!row.dataset.searchText.includes(q));});}if(e.target.matches('[data-supplier-search]')){const q=e.target.value.trim().toLocaleLowerCase('id-ID');e.target.closest('.option-field').querySelectorAll('[data-option-row]').forEach(row=>row.classList.toggle('hidden',!row.dataset.searchText.includes(q)));}if(e.target.matches('[data-medicine-search]')){const field=e.target.closest('.option-field');const q=e.target.value.trim().toLocaleLowerCase('id-ID');let visible=0;field.querySelectorAll('[data-option-row]').forEach(row=>{const match=row.dataset.searchText.includes(q);row.classList.toggle('hidden',!match);if(match)visible++;});field.querySelector('[data-medicine-empty]').classList.toggle('hidden',visible>0);}});
document.addEventListener('click',e=>{const btn=e.target.closest('[data-sort-table][data-sort-key]');if(!btn)return;const table=btn.dataset.sortTable,key=btn.dataset.sortKey;const cfg=state.tableSort[table];if(!cfg)return;if(cfg.key===key)cfg.dir=cfg.dir==='asc'?'desc':'asc';else{cfg.key=key;cfg.dir='asc';}document.querySelectorAll(`[data-sort-table="${table}"] .sort-indicator`).forEach(ind=>{const b=ind.closest('[data-sort-key]');ind.textContent=b?.dataset.sortKey===cfg.key?(cfg.dir==='asc'?'▲':'▼'):'↕';});renderMedicines();renderReceipts();renderMovements();});
$('#dataForm').addEventListener('submit',async e=>{e.preventDefault();if(!supabase||!state.user)return;const type=state.modalType;const btn=$('#modalSubmit');btn.disabled=true;$('#modalError').textContent='';try{const values=Object.fromEntries(new FormData(e.currentTarget).entries());if(type==='obat'){const payload={...values};payload.stok_minimum=payload.stok_minimum===''?0:Number(payload.stok_minimum);payload.jenis_obat=payload.jenis_obat?.trim()||null;payload.harga_jual=Number(String(payload.harga_jual||'').replace(/\./g,''));if(!payload.kode_obat||!payload.nama_obat)throw new Error('Kode dan nama obat wajib diisi.');if(!payload.bentuk_sediaan||!payload.kategori||!payload.satuan_dasar)throw new Error('Bentuk sediaan, kategori obat, dan satuan stok wajib dipilih.');if(!Number.isFinite(payload.harga_jual)||payload.harga_jual<0)throw new Error('Harga jual harus berupa angka nol atau lebih.');if(state.editId){const {error}=await supabase.from('obat').update(payload).eq('id',state.editId);if(error)throw error;}else{const {error}=await supabase.from('obat').insert(payload);if(error)throw error;}toast(state.editId?'Data obat berhasil diperbarui.':'Data obat berhasil ditambahkan. Catat batch dan stok awal melalui Stok Masuk.');}else if(type==='supplier'){const payload={...values};const query=state.editId?supabase.from('supplier').update(payload).eq('id',state.editId):supabase.from('supplier').insert(payload);const {error}=await query;if(error)throw error;toast(state.editId?'Data berhasil diperbarui.':'Data berhasil disimpan.');}else if(type==='masuk'){await saveIncoming(values);}else if(type==='masuk-edit'){await updateIncoming(state.editId,values);}else if(type==='keluar'){await saveOutgoing(values);}closeModal();await loadAll();}catch(err){$('#modalError').textContent=authError(err);console.error(err);}finally{btn.disabled=false;}});
async function saveIncoming(v){const qty=Number(v.jumlah);const invoice=`FC-${String(v.tanggal_penerimaan||today()).replace(/-/g,'')}-${Date.now().toString().slice(-6)}`;const batch=String(v.nomor_batch||'').trim();if(!v.obat_id)throw new Error('Pilih obat terlebih dahulu.');if(!batch)throw new Error('Nomor batch wajib diisi.');if(!v.tanggal_kedaluwarsa)throw new Error('Tanggal kedaluwarsa wajib diisi.');if(!Number.isFinite(qty)||qty<=0)throw new Error('Jumlah masuk harus lebih besar dari nol.');const {error}=await supabase.rpc('catat_stok_masuk',{p_supplier_id:v.supplier_id||null,p_nomor_faktur:invoice,p_tanggal_penerimaan:v.tanggal_penerimaan||today(),p_catatan:String(v.catatan||'').trim()||null,p_obat_id:v.obat_id,p_nomor_batch:batch,p_tanggal_kedaluwarsa:v.tanggal_kedaluwarsa,p_jumlah:qty});if(error){if(/function.*catat_stok_masuk|could not find the function/i.test(error.message||''))throw new Error('Fungsi catat_stok_masuk versi tanpa harga beli belum tersedia di Supabase. Jalankan file migration_hapus_harga_beli.sql, lalu coba lagi.');throw error;}toast('Penerimaan berhasil dicatat; saldo batch dan mutasi stok telah diperbarui.');}
async function updateIncoming(receiptId,v){const qty=Number(v.jumlah);if(!v.obat_id)throw new Error('Pilih obat terlebih dahulu.');if(!String(v.nomor_batch||'').trim())throw new Error('Nomor batch wajib diisi.');if(!v.tanggal_kedaluwarsa)throw new Error('Tanggal kedaluwarsa wajib diisi.');if(!Number.isFinite(qty)||qty<=0)throw new Error('Jumlah masuk harus lebih besar dari nol.');const detail=receiptDetailFor(receiptId);if(!detail)throw new Error('Detail penerimaan tidak ditemukan.');const {error}=await supabase.rpc('ubah_stok_masuk',{p_penerimaan_id:receiptId,p_supplier_id:v.supplier_id||null,p_tanggal_penerimaan:v.tanggal_penerimaan||today(),p_catatan:String(v.catatan||'').trim()||null,p_detail_id:detail.id,p_obat_id:v.obat_id,p_nomor_batch:String(v.nomor_batch).trim(),p_tanggal_kedaluwarsa:v.tanggal_kedaluwarsa,p_jumlah:qty});if(error){if(/function.*ubah_stok_masuk|could not find the function/i.test(error.message||''))throw new Error('Fungsi edit stok masuk belum tersedia. Jalankan file migration_edit_stok_masuk.sql di Supabase SQL Editor.');throw error;}toast('Detail penerimaan berhasil diperbarui; saldo batch dan mutasi stok telah disesuaikan.');}
async function saveOutgoing(v){const qty=Number(v.jumlah);if(!Number.isFinite(qty)||qty<=0)throw new Error('Jumlah keluar harus lebih besar dari nol.');const {error}=await supabase.rpc('catat_stok_keluar',{p_batch_id:v.batch_id,p_jumlah:qty,p_referensi:v.referensi||null,p_catatan:v.catatan||null});if(error)throw error;toast('Pengeluaran dan mutasi stok berhasil dicatat.');}

async function deleteRow(type,id){if(!confirm('Hapus data ini? Tindakan ini tidak dapat dibatalkan.'))return;try{const {error}=await supabase.from(type==='obat'?'obat':'supplier').delete().eq('id',id);if(error)throw error;toast('Data berhasil dihapus.');await loadAll();}catch(err){toast(`Data tidak dapat dihapus: ${authError(err)}`);}}
function exportCsv(kind){let rows=[],filename=`finkacare-${kind}-${today()}.csv`;if(kind==='obat'){rows=[['kode_obat','nama_obat','kategori','bentuk_sediaan','satuan','stok_minimum','stok_tersedia','harga_jual'],...state.medicines.map(m=>[m.kode_obat,m.nama_obat,m.kategori,m.bentuk_sediaan,m.satuan_dasar,m.stok_minimum,medicineStock(m.id),m.harga_jual])];}else if(kind==='batch'){rows=[['nama_obat','nomor_batch','tanggal_kedaluwarsa','stok_tersedia','status'],...state.batches.map(b=>[batchMedicine(b)?.nama_obat,b.nomor_batch,b.tanggal_kedaluwarsa,b.stok_tersedia,batchStatus(b).text])];}else if(kind==='mutasi'){rows=[['created_at','jenis_mutasi','nama_obat','nomor_batch','jumlah','referensi','catatan'],...state.movements.map(m=>{const b=state.batches.find(x=>x.id===m.batch_id);return[m.created_at,m.jenis_mutasi,batchMedicine(b)?.nama_obat,b?.nomor_batch,m.jumlah,m.referensi,m.catatan];})];}else{rows=[['kode_obat','nama_obat','satuan','jumlah_stok'],...state.medicines.map(m=>[m.kode_obat,m.nama_obat,m.satuan_dasar,medicineStock(m.id)])];}const csv=rows.map(row=>row.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\r\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.click();URL.revokeObjectURL(url);toast('File CSV berhasil disiapkan.');}

if(supabase){supabase.auth.getSession().then(async({data,error})=>{if(error){showAuth();return;}if(data.session){state.session=data.session;state.user=data.session.user;await startApp();}else showAuth();});supabase.auth.onAuthStateChange(async(event,session)=>{if(event==='SIGNED_OUT'||!session){state.session=null;state.user=null;showAuth();}else if(session&&(!state.user||state.user.id!==session.user.id)){state.session=session;state.user=session.user;await startApp();}});}else{showAuth();}
